1	"use client";
2	
3	import { useState, useEffect, useCallback } from "react";
4	import { useRouter, useSearchParams } from "next/navigation";
5	import { useAuth } from "@/lib/auth-context";
6	import { Button } from "@/components/ui/button";
7	import { Input } from "@/components/ui/input";
8	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
9	import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
10	import { Badge } from "@/components/ui/badge";
11	import { ProtectedRoute } from "@/components/protected-route";
12	import Link from "next/link";
13	import { Plus, Search, Filter, ChevronLeft, ChevronRight, Edit, Archive, Eye, RotateCcw } from "lucide-react";
14	import { format } from "date-fns";
15	
16	interface Customer {
17	  id: number;
18	  name: string;
19	  mobile: string;
20	  email: string | null;
21	  address: string | null;
22	  notes: string | null;
23	  status: string;
24	  primary_staff_id: number | null;
25	  primary_staff_name: string | null;
26	  shop_id: number;
27	  created_at: string;
28	  updated_at: string;
29	}
30	
31	interface CustomerListResponse {
32	  items: Customer[];
33	  total: number;
34	  page: number;
35	  page_size: number;
36	  total_pages: number;
37	}
38	
39	function CustomersContent() {
40	  const { user, loading: authLoading } = useAuth();
41	  const router = useRouter();
42	  const searchParams = useSearchParams();
43	
44	  const [customers, setCustomers] = useState<Customer[]>([]);
45	  const [loading, setLoading] = useState(true);
46	  const [error, setError] = useState<string | null>(null);
47	  const [total, setTotal] = useState(0);
48	  const [page, setPage] = useState(1);
49	  const [pageSize, setPageSize] = useState(10);
50	  const [totalPages, setTotalPages] = useState(0);
51	  const [search, setSearch] = useState(searchParams?.get("search") || "");
52	  const [statusFilter, setStatusFilter] = useState(searchParams?.get("status") || "");
53	  const [staffFilter, setStaffFilter] = useState(searchParams?.get("primary_staff_id") || "");
54	
55	  const shopIdParam = searchParams?.get("shop_id");
56	  const [shopId, setShopId] = useState<number | null>(shopIdParam ? parseInt(shopIdParam, 10) : null);
57	
58	  const fetchCustomers = useCallback(async () => {
59	    if (!shopId) return;
60	
61	    setLoading(true);
62	    setError(null);
63	
64	    try {
65	      const params = new URLSearchParams({
66	        page: page.toString(),
67	        page_size: pageSize.toString(),
68	      });
69	
70	      if (search) params.append("search", search);
71	      if (statusFilter) params.append("status", statusFilter);
72	      if (staffFilter) params.append("primary_staff_id", staffFilter);
73	
74	      const response = await fetch(`/api/v1/shops/${shopId}/customers?${params}`, {
75	        headers: {
76	          "Authorization": `Bearer ${localStorage.getItem("access_token")}`,
77	        },
78	      });
79	
80	      if (!response.ok) {
81	        if (response.status === 401) {
82	          router.push("/login");
83	          return;
84	        }
85	        throw new Error("Failed to fetch customers");
86	      }
87	
88	      const data: CustomerListResponse = await response.json();
89	      setCustomers(data.items);
90	      setTotal(data.total);
91	      setTotalPages(data.total_pages);
92	    } catch (err) {
93	      setError(err instanceof Error ? err.message : "An error occurred");
94	    } finally {
95	      setLoading(false);
96	    }
97	  }, [shopId, page, pageSize, search, statusFilter, staffFilter, router]);
98	
99	  useEffect(() => {
100	    fetchCustomers();
101	  }, [fetchCustomers]);
102	
103	  const handleSearch = (e: React.FormEvent) => {
104	    e.preventDefault();
105	    setPage(1);
106	    const params = new URLSearchParams(searchParams?.toString() || "");
107	    if (search) params.set("search", search);
108	    else params.delete("search");
109	    router.push(`/dashboard/customers?${params.toString()}`);
110	  };
111	
112	  const handleFilterChange = (key: string, value: string) => {
113	    setPage(1);
114	    const params = new URLSearchParams(searchParams?.toString() || "");
115	    if (value) params.set(key, value);
116	    else params.delete(key);
117	    router.push(`/dashboard/customers?${params.toString()}`);
118	  };
119	
120	  const getStatusBadge = (status: string) => {
121	    const variants: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
122	      active: "default",
123	      inactive: "secondary",
124	      archived: "destructive",
125	    };
126	    return (
127	      <Badge variant={variants[status] || "outline"} className="capitalize">
128	        {status}
129	      </Badge>
130	    );
131	  };
132	
133	  const handleArchive = async (customerId: number) => {
134	    if (!confirm("Archive this customer?")) return;
135	    const resp = await fetch(`/api/v1/shops/${shopId}/customers/${customerId}/archive`, {
136	      method: "PATCH",
137	      headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
138	    });
139	    if (resp.ok) fetchCustomers();
140	  };
141	
142	  const handleRestore = async (customerId: number) => {
143	    if (!confirm("Restore this customer?")) return;
144	    const resp = await fetch(`/api/v1/shops/${shopId}/customers/${customerId}/restore`, {
145	      method: "PATCH",
146	      headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
147	    });
148	    if (resp.ok) fetchCustomers();
149	  };
150	
151	  if (authLoading) {
152	    return (
153	      <div className="flex min-h-screen items-center justify-center">
154	        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
155	      </div>
156	    );
157	  }
158	
159	  return (
160	    <div className="container mx-auto py-8">
161	      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
162	        <div>
163	          <h1 className="text-3xl font-bold tracking-tight">Customers</h1>
164	          <p className="text-muted-foreground mt-1">Manage your customer database</p>
165	        </div>
166	        <Button asChild>
167	          <Link href="/dashboard/customers/new">
168	            <Plus className="mr-2 h-4 w-4" />
169	            New Customer
170	          </Link>
171	        </Button>
172	      </div>
173	
174	      {/* Search and Filters */}
175	      <form onSubmit={handleSearch} className="mb-6 flex flex-col sm:flex-row gap-4">
176	        <div className="relative flex-1 max-w-md">
177	          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
178	          <Input
179	            placeholder="Search by name, mobile, or email..."
180	            value={search}
181	            onChange={(e) => setSearch(e.target.value)}
182	            className="pl-10"
183	          />
184	        </div>
185	        <div className="flex gap-2">
186	          <Select value={statusFilter} onValueChange={(v) => { setStatusFilter(v); handleFilterChange("status", v); }}>
187	            <SelectTrigger className="w-[180px]">
188	              <Filter className="mr-2 h-4 w-4" />
189	              <SelectValue placeholder="All Statuses" />
190	            </SelectTrigger>
191	            <SelectContent>
192	              <SelectItem value="">All Statuses</SelectItem>
193	              <SelectItem value="active">Active</SelectItem>
194	              <SelectItem value="inactive">Inactive</SelectItem>
195	              <SelectItem value="archived">Archived</SelectItem>
196	            </SelectContent>
197	          </Select>
198	          <Select value={staffFilter} onValueChange={(v) => { setStaffFilter(v); handleFilterChange("primary_staff_id", v); }}>
199	            <SelectTrigger className="w-[180px]">
200	              <Filter className="mr-2 h-4 w-4" />
201	              <SelectValue placeholder="All Staff" />
202	            </SelectTrigger>
203	            <SelectContent>
204	              <SelectItem value="">All Staff</SelectItem>
205	              {/* Staff would be loaded from API */}
206	            </SelectContent>
207	          </Select>
208	        </div>
209	      </form>
210	
211	      {error && (
212	        <div className="mb-6 p-4 rounded-lg bg-destructive/10 text-destructive">
213	          {error}
214	        </div>
215	      )}
216	
217	      {/* Customers Table */}
218	      <div className="rounded-lg border bg-card">
219	        <Table>
220	          <TableHeader>
221	            <TableRow>
222	              <TableHead>Name</TableHead>
223	              <TableHead>Mobile</TableHead>
224	              <TableHead>Email</TableHead>
225	              <TableHead>Primary Staff</TableHead>
