250	                  <TableCell className="font-mono">{customer.mobile}</TableCell>
251	                  <TableCell>{customer.email || "—"}</TableCell>
252	                  <TableCell>{customer.primary_staff_name || "—"}</TableCell>
253	                  <TableCell>{getStatusBadge(customer.status)}</TableCell>
254	                  <TableCell className="text-right">
255	                    <div className="flex items-center justify-end gap-2">
256	                      <Button variant="ghost" size="icon" asChild>
257	                        <Link href={`/dashboard/customers/${customer.id}`}>
258	                          <Eye className="h-4 w-4" />
