1	/**
2	 * Lightweight API client for the backend.
3	 *
4	 * - Auth requests are proxied through Next.js API routes so the browser never
5	 *   talks directly to the backend and HTTP-only cookies flow through the proxy.
6	 * - Access tokens are held **only** in memory (never localStorage/sessionStorage)
7	 *   to limit XSS exposure.
8	 */
9	
10	let accessToken: string | null = null;
11	let accessTokenExpiry: number | null = null;
12	
13	export function setAccessToken(token: string, expiresIn: number) {
14	  accessToken = token;
15	  // Set expiry slightly earlier to avoid using an about-to-expire token.
16	  accessTokenExpiry = Date.now() + (expiresIn - 30) * 1000;
17	}
18	
19	export function clearAccessToken() {
20	  accessToken = null;
21	  accessTokenExpiry = null;
22	}
23	
24	export function getAccessToken(): string | null {
25	  if (!accessToken || !accessTokenExpiry) return null;
26	  if (Date.now() >= accessTokenExpiry) return null;
27	  return accessToken;
28	}
29	
30	// Base URL for Next.js API proxy routes (same origin).
31	const AUTH_PROXY = "/api/auth";
32	
33	// Base URL for API calls via Next.js rewrites proxy to backend.
34	// Uses /api/v1 which is rewritten to http://backend:8000/api/v1 by next.config.mjs
35	const API_BASE =
36	  process.env.NEXT_PUBLIC_API_BASE_URL ?? "/api/v1";
37	
38	/** Authenticated fetch against the backend API. */
39	export async function apiFetch(
40	  path: string,
41	  init: RequestInit = {}
42	): Promise<Response> {
43	  const headers = new Headers(init.headers);
44	  const token = getAccessToken();
45	  if (token) {
46	    headers.set("Authorization", `Bearer ${token}`);
47	  }
48	  headers.set("Content-Type", "application/json");
