// ── Auth API (proxied through Next.js for cookie management) ──────────────

export interface AuthUser {
  id: number;
  email: string;
  full_name: string;
  platform_role: string | null;
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

export interface LoginResponse {
  access_token: string;
  token_type: string;
  expires_in: number;
  user: AuthUser;
}

export async function login(
  email: string,
  password: string
): Promise<LoginResponse> {
  const res = await fetch(`${AUTH_PROXY}/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
    credentials: "include",
  });
  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new ApiError(res.status, body?.error?.message ?? "Login failed");
  }
  const data: LoginResponse = await res.json();
  setAccessToken(data.access_token, data.expires_in);
  return data;
}

export async function refreshToken(): Promise<LoginResponse | null> {
  const res = await fetch(`${AUTH_PROXY}/refresh`, {
    method: "POST",
    credentials: "include",
  });
  if (!res.ok) return null;
  const data: LoginResponse = await res.json();
  setAccessToken(data.access_token, data.expires_in);
  return data;
}

export async function logout(): Promise<void> {
  await fetch(`${AUTH_PROXY}/logout`, {
    method: "POST",
    credentials: "include",
    headers: accessToken
      ? { Authorization: `Bearer ${accessToken}` }
      : undefined,
  });
  clearAccessToken();
}

export async function fetchCurrentUser(): Promise<AuthUser> {
  const token = getAccessToken();
  if (!token) throw new ApiError(401, "Not authenticated");
  const res = await fetch(`${AUTH_PROXY}/me`, {
    headers: { Authorization: `Bearer ${token}` },
    credentials: "include",
  });
  if (!res.ok) throw new ApiError(res.status, "Failed to load user");
  return res.json();
}

export class ApiError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.name = "ApiError";
    this.status = status;
  }
}

