  period_from: string;
  period_to: string;
  staff: StaffReportItem[];
}

export interface OutstandingItem {
  billing_id: number;
  invoice_number: string;
  application_number: string;
  customer_name: string;
  service_name: string;
  total_amount: string;
  paid_amount: string;
