60	  created_at: string;
61	  updated_at: string;
62	  primary_owner?: {
63	    id: number;
64	    email: string;
65	    full_name: string;
66	  } | null;
67	}
68	
69	export interface ShopListResponse {
70	  items: Shop[];
71	  total: number;
72	  page: number;
73	  page_size: number;
74	  total_pages: number;
75	}
