145	}
146	
147	// ── Auth API (proxied through Next.js for cookie management) ──────────────
148	
149	export interface AuthUser {
150	  id: number;
151	  email: string;
152	  full_name: string;
153	  platform_role: string | null;
154	  is_active: boolean;
155	  created_at: string;
156	  updated_at: string;
157	}
158	
159	export interface LoginResponse {
160	  access_token: string;
161	  token_type: string;
162	  expires_in: number;
163	  user: AuthUser;
164	}
165	
166	export async function login(
167	  email: string,
168	  password: string
169	): Promise<LoginResponse> {
170	  const res = await fetch(`${AUTH_PROXY}/login`, {
171	    method: "POST",
172	    headers: { "Content-Type": "application/json" },
173	    body: JSON.stringify({ email, password }),
174	    credentials: "include",
175	  });
176	  if (!res.ok) {
177	    const body = await res.json().catch(() => ({}));
178	    throw new ApiError(res.status, body?.error?.message ?? "Login failed");
179	  }
180	  const data: LoginResponse = await res.json();
181	  setAccessToken(data.access_token, data.expires_in);
182	  return data;
183	}
184	
185	export async function refreshToken(): Promise<LoginResponse | null> {
186	  const res = await fetch(`${AUTH_PROXY}/refresh`, {
187	    method: "POST",
188	    credentials: "include",
189	  });
190	  if (!res.ok) return null;
191	  const data: LoginResponse = await res.json();
192	  setAccessToken(data.access_token, data.expires_in);
193	  return data;
194	}
195	
196	export async function logout(): Promise<void> {
197	  await fetch(`${AUTH_PROXY}/logout`, {
198	    method: "POST",
199	    credentials: "include",
200	    headers: accessToken
201	      ? { Authorization: `Bearer ${accessToken}` }
202	      : undefined,
203	  });
204	  clearAccessToken();
205	}
206	
207	export async function fetchCurrentUser(): Promise<AuthUser> {
208	  const token = getAccessToken();
209	  if (!token) throw new ApiError(401, "Not authenticated");
210	  const res = await fetch(`${AUTH_PROXY}/me`, {
211	    headers: { Authorization: `Bearer ${token}` },
212	    credentials: "include",
213	  });
214	  if (!res.ok) throw new ApiError(res.status, "Failed to load user");
215	  return res.json();
216	}
217	
218	export class ApiError extends Error {
219	  status: number;
220	  constructor(status: number, message: string) {
221	    super(message);
222	    this.name = "ApiError";
223	    this.status = status;
224	  }
225	}
226	
227	// ── Platform Shops API ──────────────────────────────────────────────────────
228	
229	export const platformApi = {
230	  /** List shops with search, status filter, pagination */
231	  async listShops(params: PaginatedParams = {}): Promise<ShopListResponse> {
232	    const searchParams = new URLSearchParams();
233	    if (params.page) searchParams.set("page", String(params.page));
234	    if (params.page_size) searchParams.set("page_size", String(params.page_size));
235	    if (params.search) searchParams.set("search", params.search);
236	    if (params.status) searchParams.set("status", params.status);
237	    const res = await apiFetch(`/platform/shops?${searchParams.toString()}`);
238	    if (!res.ok) throw new ApiError(res.status, "Failed to list shops");
239	    return res.json();
240	  },
241	
242	  /** Create a new shop */
243	  async createShop(payload: CreateShopPayload): Promise<Shop> {
244	    const res = await apiFetch("/platform/shops", {
245	      method: "POST",
246	      body: JSON.stringify(payload),
247	    });
248	    if (!res.ok) {
249	      const body = await res.json().catch(() => ({}));
250	      throw new ApiError(res.status, body?.error?.message ?? "Failed to create shop");
251	    }
252	    return res.json();
253	  },
254	
255	  /** Get shop by ID */
256	  async getShop(shopId: number): Promise<Shop> {
257	    const res = await apiFetch(`/platform/shops/${shopId}`);
258	    if (!res.ok) throw new ApiError(res.status, "Failed to fetch shop");
259	    return res.json();
260	  },
261	
262	  /** Update shop name/slug */
263	  async updateShop(shopId: number, payload: UpdateShopPayload): Promise<Shop> {
264	    const res = await apiFetch(`/platform/shops/${shopId}`, {
265	      method: "PATCH",
266	      body: JSON.stringify(payload),
267	    });
268	    if (!res.ok) throw new ApiError(res.status, "Failed to update shop");
269	    return res.json();
